function filterScholarships(){const scholarshipSearch=document.getElementById("scholarshipSearch");const scholarshipCards=document.querySelectorAll(".scholarship-card");const noScholarshipFoundMsg=document.getElementById("noScholarshipFoundMsg");const activeBtn=document.querySelector(".sch-filter-btn.active");if(!scholarshipCards||scholarshipCards.length===0)return;const selectedCategory=activeBtn?activeBtn.getAttribute("data-category"):"all";const searchQuery=scholarshipSearch?scholarshipSearch.value.toLowerCase().trim():"";let visibleCount=0;scholarshipCards.forEach(card=>{const cardCategory=card.getAttribute("data-category");const cardText=card.innerText.toLowerCase();const matchesCategory=selectedCategory==="all"||cardCategory===selectedCategory;const matchesSearch=!searchQuery||cardText.includes(searchQuery);if(matchesCategory&&matchesSearch){card.style.display="flex";visibleCount++;}else{card.style.display="none";}});if(noScholarshipFoundMsg){noScholarshipFoundMsg.style.display=visibleCount===0?"block":"none";}}
function handleStatePillClick(stateId,e){if(e)e.preventDefault();const resultContainer=document.getElementById("stateScholarshipsResult");const allPanels=document.querySelectorAll(".state-panel");const statePills=document.querySelectorAll(".state-pill");if(!resultContainer)return;resultContainer.style.display="flex";allPanels.forEach(panel=>panel.style.display="none");const targetPanel=document.getElementById("panel-state-"+stateId);if(targetPanel){targetPanel.style.display="flex";}else{const def=document.getElementById("panel-state-default");if(def)def.style.display="block";}
statePills.forEach(p=>{const pState=p.getAttribute("data-state")||(p.getAttribute("href")&&p.getAttribute("href").includes("state=")?p.getAttribute("href").split("state=")[1]:"");if(pState===stateId){p.style.background="var(--gold-gradient)";p.style.color="#000";p.style.borderColor="transparent";p.style.fontWeight="800";}else{p.style.background="var(--bg-secondary)";p.style.color="var(--text-primary)";p.style.borderColor="var(--border-color)";p.style.fontWeight="normal";}});setTimeout(()=>{const scrollTarget=targetPanel||resultContainer;if(scrollTarget){scrollTarget.scrollIntoView({behavior:"smooth",block:"center"});}},100);}
function initScholarships(){const scholarshipSearch=document.getElementById("scholarshipSearch");const scholarshipFilterBtns=document.querySelectorAll(".sch-filter-btn");const statePills=document.querySelectorAll(".state-pill");scholarshipFilterBtns.forEach(btn=>{btn.addEventListener("click",()=>{scholarshipFilterBtns.forEach(b=>b.classList.remove("active"));btn.classList.add("active");filterScholarships();});});if(scholarshipSearch){scholarshipSearch.addEventListener("input",filterScholarships);}
statePills.forEach(pill=>{pill.addEventListener("click",(e)=>{const stateId=pill.getAttribute("data-state")||(pill.getAttribute("href")&&pill.getAttribute("href").includes("state=")?pill.getAttribute("href").split("state=")[1]:"");if(stateId){handleStatePillClick(stateId,e);}});});const urlParams=new URLSearchParams(window.location.search);const stateParam=urlParams.get("state");if(stateParam){handleStatePillClick(stateParam);}}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initScholarships);}else{initScholarships();}